CREATE TABLE cmdb_ire_quality_metrics (tenant_id BIGINT UNSIGNED NOT NULL, rule_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, valid_count BIGINT UNSIGNED NOT NULL, denominator BIGINT UNSIGNED NOT NULL, open_count BIGINT UNSIGNED NOT NULL, checked_at DATETIME(6) NOT NULL, PRIMARY KEY(tenant_id,rule_key), CONSTRAINT cmdb_ire_quality_metric_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
